import json,yaml
def render(run,chart,overrides):
    args=['template','anchor-check',str(chart)]
    expanded=dict(overrides)
    if 'base.host' in overrides:
        expanded.setdefault('left.host',overrides['base.host']);expanded.setdefault('right.host',overrides['base.host'])
    for path,value in expanded.items():args+=['--set-string',path+'='+value]
    code,out,err=run(args)
    if code:raise RuntimeError('Helm render failed')
    return json.loads(next(d for d in yaml.safe_load_all(out) if d)['data']['expanded'])
